import {Simulation,DEFINITIONS,TRAITS,BURN_P,BURN_B,SIZE,terrain,elevation,fertility} from './simulation.mjs';
import {Renderer,iso} from './renderer.mjs?v=stage1';
const $=id=>document.getElementById(id);let sim=new Simulation(),speed=1,tool='inspect',selected=null,last=performance.now(),uiClock=0,saveClock=0;
const renderer=new Renderer($('world'),$('minimap'));
const icons={shelter:'⌂',farm:'♧',stockpile:'▤',well:'◉',workshop:'⚒',path:'⌁',clear:'✂'},labels={shelter:'Shelter',farm:'Garden',stockpile:'Storehouse',well:'Well',workshop:'Workshop',path:'Path',clear:'Clear'};
$('buildTools').innerHTML=Object.entries(DEFINITIONS).map(([key,d],i)=>`<button class="tool" data-tool="${key}" title="${d.name} — ${d.description}"><span class="toolicon">${icons[key]}</span><span>${labels[key]}</span><small>${d.wood?d.wood+' wood':''}${d.stone?' · '+d.stone+' stone':''}${!d.wood?'Free':''}</small></button>`).join('');
renderer.ready.then(()=>{for(const type of Object.keys(DEFINITIONS)){const target=document.querySelector(`[data-tool="${type}"] .toolicon`);if(target){const img=document.createElement('img');img.src=renderer.icon(type);img.alt='';target.replaceChildren(img);}}});
$('priorities').innerHTML=['build','food','wood','stone'].map(k=>`<button data-priority="${k}" class="active" aria-pressed="true">${{build:'Build',food:'Food',wood:'Wood',stone:'Stone'}[k]}</button>`).join('');
const soilWord=v=>v<.3?'poor':v<.48?'thin':v<.66?'good':'rich';
const groundWord={grass:'Meadow and woodland soil',sand:'River shingle',water:'Open water',scree:'Loose scree',rock:'Upland rock',void:'Beyond the valley'};
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),3200);}
function selectTool(next){tool=next;renderer.tool=tool;selected=null;renderer.selected=null;$('inspector').hidden=true;document.body.classList.toggle('placing',tool!=='inspect');document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));updateUI();}
function setSpeed(next){speed=next;document.querySelectorAll('[data-speed]').forEach(b=>{b.classList.toggle('active',+b.dataset.speed===speed);b.setAttribute('aria-pressed',String(+b.dataset.speed===speed));});}
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>selectTool(b.dataset.tool));document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>setSpeed(+b.dataset.speed));
document.querySelectorAll('[data-priority]').forEach(b=>b.onclick=()=>{sim.priorities[b.dataset.priority]=!sim.priorities[b.dataset.priority];updateUI();});
function save(checkpoint=false){try{const data=JSON.stringify(sim.snapshot());localStorage.setItem('threefold-autosave',data);if(checkpoint)localStorage.setItem('threefold-checkpoint',data);$('saveStatus').textContent=checkpoint?'Checkpoint saved':'Autosaved';if(checkpoint)toast('Your valley is saved on this device.');return true;}catch{$('saveStatus').textContent='Save unavailable';if(checkpoint)toast('This browser could not save your valley.');return false;}}
function load(checkpoint=false){try{const raw=localStorage.getItem(checkpoint?'threefold-checkpoint':'threefold-autosave');if(!raw){if(checkpoint)toast('No checkpoint yet. Use Save to create one.');return false;}sim=Simulation.restore(JSON.parse(raw));selected=null;renderer.selected=null;updateUI();if(checkpoint)toast('Your saved checkpoint has been restored.');return true;}catch{if(checkpoint)toast('The save could not be opened. Your current valley is safe.');else try{localStorage.removeItem('threefold-autosave');}catch{}return false;}}
$('save').onclick=()=>save(true);$('load').onclick=()=>load(true);$('restart').onclick=()=>$('newDialog').showModal();$('confirmNew').onclick=()=>{sim=new Simulation();selectTool('inspect');setSpeed(1);home();save(true);toast('A new valley. Three new beginnings.');};$('helpButton').onclick=()=>$('help').showModal();
function home(){const p=iso(sim.people.reduce((n,p)=>n+p.x,0)/sim.people.length,sim.people.reduce((n,p)=>n+p.y,0)/sim.people.length);renderer.camera.x=p.x;renderer.camera.y=p.y;renderer.camera.zoom=.92;}
$('home').onclick=home;$('zoomOut').onclick=()=>renderer.zoom(.8);$('zoomIn').onclick=()=>renderer.zoom(1.25);
function inspect(t){let p=sim.people.find(p=>Math.hypot(p.x-t.x,p.y-t.y)<.9);let b=sim.buildings.find(b=>t.x>=b.x&&t.y>=b.y&&t.x<b.x+DEFINITIONS[b.type].size&&t.y<b.y+DEFINITIONS[b.type].size);let n=sim.nodes.find(n=>n.amount>0&&n.x===t.x&&n.y===t.y);selected=p?{kind:'person',id:p.id}:b?{kind:'building',id:b.id}:n?{kind:'node',id:n.id}:terrain(t.x,t.y)==='void'?null:{kind:'ground',x:t.x,y:t.y};renderer.selected=selected;updateInspector();}
function placeAt(t,quiet=false){const result=sim.place(tool,t.x,t.y);if(!result.ok&&!quiet)toast(result.error);if(result.ok&&!DEFINITIONS[tool].order)toast(`${DEFINITIONS[tool].name} planned. Settlers will start work.`);updateUI();return result;}
let pointer=null,dragging=false,pointers=new Map(),pinch=null,pathLast=null;
const canvas=$('world');canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()];pinch=Math.hypot(a.x-b.x,a.y-b.y);dragging=true;return;}pointer={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,button:e.button};dragging=false;pathLast=null;if(DEFINITIONS[tool]?.order&&e.button===0){const t=renderer.tile(e.clientX,e.clientY);placeAt(t,true);pathLast=t.x+','+t.y;}});
canvas.addEventListener('pointermove',e=>{renderer.hover=renderer.tile(e.clientX,e.clientY);if(pointers.has(e.pointerId))pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],next=Math.hypot(a.x-b.x,a.y-b.y);if(pinch)renderer.zoom(next/pinch,(a.x+b.x)/2,(a.y+b.y)/2);pinch=next;return;}if(!pointer||!pointers.has(e.pointerId))return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.hypot(e.clientX-pointer.startX,e.clientY-pointer.startY)>5)dragging=true;if(DEFINITIONS[tool]?.order&&pointer.button===0){const t=renderer.hover,key=t.x+','+t.y;if(key!==pathLast){placeAt(t,true);pathLast=key;}}else if(dragging){renderer.camera.x-=dx/renderer.ratio/renderer.camera.zoom;renderer.camera.y-=dy/renderer.ratio/renderer.camera.zoom;document.body.classList.add('dragging');}pointer.x=e.clientX;pointer.y=e.clientY;});
canvas.addEventListener('pointerup',e=>{const wasPinch=pinch!==null;pointers.delete(e.pointerId);if(!dragging&&!wasPinch&&pointer?.button===0){const t=renderer.tile(e.clientX,e.clientY);if(tool==='inspect')inspect(t);else if(!DEFINITIONS[tool].order)placeAt(t);}if(!pointers.size){pointer=null;pinch=null;dragging=false;document.body.classList.remove('dragging');}else{pointer=null;}});canvas.addEventListener('pointercancel',()=>{pointers.clear();pointer=null;pinch=null;dragging=false;});canvas.addEventListener('pointerleave',()=>{renderer.hover=null;});canvas.addEventListener('contextmenu',e=>{e.preventDefault();selectTool('inspect');});canvas.addEventListener('wheel',e=>{e.preventDefault();renderer.zoom(Math.exp(-e.deltaY*.0012),e.clientX,e.clientY);},{passive:false});
$('minimap').onclick=e=>{const box=$('minimap').getBoundingClientRect(),m=renderer.miniScale();const x=((e.clientX-box.left)*$('minimap').width/box.width-m.offX)/m.scale,y=((e.clientY-box.top)*$('minimap').height/box.height-m.offY)/m.scale,p=iso(Math.max(0,Math.min(SIZE-1,x)),Math.max(0,Math.min(SIZE-1,y)));renderer.camera.x=p.x;renderer.camera.y=p.y;};
const keys=new Set();window.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;const key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright','home'].includes(key))e.preventDefault();keys.add(key);if(e.repeat)return;if(key===' ')setSpeed(speed?0:1);if(key==='escape')selectTool('inspect');if(key==='home')home();if(key==='+'||key==='=')renderer.zoom(1.2);if(key==='-')renderer.zoom(1/1.2);if(/^[1-7]$/.test(key))selectTool(Object.keys(DEFINITIONS)[Number(key)-1]);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());window.addEventListener('resize',()=>renderer.resize());window.addEventListener('pagehide',()=>save());
function meter(label,value){return `<div class="meterlabel"><span>${label}</span><span>${Math.round(value)}%</span></div><div class="meter"><span style="width:${Math.min(100,Math.max(0,value))}%"></span></div>`;}
function updateInspector(){const el=$('inspector');if(!selected){el.hidden=true;return;}el.hidden=false;let html='<button class="close" id="closeInspector" aria-label="Close details">×</button>';
 if(selected.kind==='person'){const p=sim.people.find(p=>p.id===selected.id);if(!p){selected=null;return;}html+=`<span class="eyebrow">${p.id===sim.people[0].id||sim.people.indexOf(p)<3?'FOUNDER':'SETTLER'}</span><h2>${p.name}</h2><p class="trade">${TRAITS[p.trait].name} · ${TRAITS[p.trait].blurb}</p><p>${p.action}${p.carrying?' · '+p.carrying.amount+' '+p.carrying.type:''}</p>${meter('Well fed',100-p.hunger)}${meter('Energy',p.energy)}${meter('Hydration',100-p.thirst)}${meter('Spirits',p.morale)}<div class="skills">${Object.entries(p.skills).map(([k,v])=>`<span><b>${TRAITS[k].name}</b>${v.toFixed(2)}×</span>`).join('')}</div><p class="muted">Walks at ${Math.round(p.speed*100)}% pace.</p><p>${p.history}</p>`;}
 else if(selected.kind==='building'){const b=sim.buildings.find(b=>b.id===selected.id);if(!b){selected=null;el.hidden=true;return;}const d=DEFINITIONS[b.type];html+=`<span class="eyebrow">${b.complete?'PART OF YOUR SETTLEMENT':'UNDER CONSTRUCTION'}</span><h2>${d.name}</h2><p>${d.description}</p>${!b.complete?meter('Construction',b.progress/d.work*100)+'<button class="cancel" id="cancelBuild">Cancel & return materials</button>':meter('Condition',b.condition)+(b.type==='farm'?meter('Ready to harvest',b.harvest/30*100)+meter('Soil',(b.soil??.5)*100)+`<p class="muted">Planted on ${soilWord(b.soil??.5)} soil.</p>`:'')+`<p class="muted">Repairs cost ${d.upkeep.wood} wood${d.upkeep.stone?' and '+d.upkeep.stone+' stone':''}. Settlers see to it below 62%${b.condition<62?' — they are on their way.':'.'}</p>`}`;}
 else if(selected.kind==='ground'){const k=terrain(selected.x,selected.y),soil=fertility(selected.x,selected.y),h=elevation(selected.x,selected.y);
  html+=`<span class="eyebrow">THE LAND</span><h2>${groundWord[k]}</h2>${k==='water'?'<p>Settlers drink here, and nothing can be built on it.</p>':`<p>Soil is <b>${soilWord(soil)}</b> here — a garden on this ground yields ${Math.round((.45+1.15*soil)/(.45+1.15*.5)*100)}% of what one on average soil would.</p>`}${meter('Soil',soil*100)}${meter('Height',h*100)}<p class="muted">${k==='rock'||k==='scree'?'Hard going underfoot: settlers cross high ground more slowly, but stone is plentiful up here.':k==='grass'?'Easy ground to cross and to build on.':''}</p>`;}
 else {const n=sim.nodes.find(n=>n.id===selected.id);html+=`<span class="eyebrow">THE WILDERNESS</span><h2>${n.type==='tree'?'Standing timber':n.type==='stone'?'Stone outcrop':'Wild berries'}</h2><p>${n.amount} ${n.type==='tree'?'timber':n.type==='stone'?'stone':'food'} remaining. Your people gather this when the corresponding work priority is enabled.</p>${n.marked?'<p class="marked">Marked for clearing. A settler will fell it and carry everything home, leaving the ground free to build on.</p><button class="cancel" id="unmark">Leave it standing</button>':'<p class="muted">Use the Clear tool to fell it and free the ground.</p>'}`;}
 el.innerHTML=html;$('closeInspector').onclick=()=>{selected=null;renderer.selected=null;el.hidden=true;};if($('cancelBuild'))$('cancelBuild').onclick=()=>{sim.cancel(selected.id);selected=null;renderer.selected=null;updateUI();};if($('unmark'))$('unmark').onclick=()=>{sim.unmark(selected.id);updateUI();};}
function updateUI(){for(const k of ['wood','food','stone'])$(k).textContent=Math.floor(sim.resources[k]);$('population').textContent=sim.people.length;$('day').textContent='Day '+(Math.floor(sim.time/120)+1);$('season').textContent=speed===0?'TIME PAUSED':sim.time%120>86?'EVENING · SPRING':'EARLY SPRING';$('zoomLabel').textContent=Math.round(renderer.camera.zoom/.92*100)+'%';
 $('settlers').innerHTML=sim.people.slice(0,6).map(p=>`<button class="settler" data-person="${p.id}" aria-label="Inspect ${p.name}"><span class="avatar">${p.name[0]}</span><span><strong>${p.name}</strong><small>${p.action}</small></span></button>`).join('')+(sim.people.length>6?`<p class="intro">And ${sim.people.length-6} more settlers</p>`:'');document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{selected={kind:'person',id:+b.dataset.person};renderer.selected=selected;const p=sim.people.find(p=>p.id===selected.id),pos=iso(p.x,p.y);renderer.camera.x=pos.x;renderer.camera.y=pos.y;updateInspector();});
 document.querySelectorAll('[data-priority]').forEach(b=>{b.classList.toggle('active',sim.priorities[b.dataset.priority]);b.setAttribute('aria-pressed',String(sim.priorities[b.dataset.priority]));});
 const homes=sim.buildings.filter(b=>b.complete&&b.type==='shelter').length*3,complete=sim.buildings.filter(b=>b.complete).length;const burn=(BURN_P*sim.people.length+BURN_B*complete)*120,frail=sim.buildings.filter(b=>b.complete&&b.condition<62).length;$('settlementStatus').innerHTML=`<b>${complete}</b> buildings · <b>${homes}</b> places to sleep<br><span class="${sim.resources.wood<1?'warn':'muted'}">${sim.resources.wood<1?'The fires are out. Bring timber home.':`Hearths burn about ${Math.round(burn)} timber a day.`}</span>${frail?`<br><span class="warn">${frail} building${frail>1?'s need':' needs'} repair.</span>`:''}<br>${homes>sim.people.length?(sim.resources.food>=24?'A traveller is considering your settlement.':'Keep 24 food in store to welcome a traveller.'):'Build spare housing to welcome new settlers.'}`;
 $('journal').innerHTML=sim.events.slice(0,2).map(e=>`<p><small>DAY ${e.day}</small>${e.text}</p>`).join('');
 if(tool!=='inspect'){const g=renderer.hover&&terrain(renderer.hover.x,renderer.hover.y)!=='void'?renderer.hover:null;
  $('hint').innerHTML=`<span>${DEFINITIONS[tool].name.toUpperCase()}</span>${tool==='farm'&&g?`Soil here is <b>${soilWord(fertility(g.x,g.y))}</b>. `:''}${tool==='path'?'Drag over clear ground to draw a path. Right-drag to pan.':tool==='clear'?'Drag over trees, rock or scrub to mark it for felling. Right-drag to pan.':'Click clear ground to place · Escape to stop building'}`;$('hint').hidden=false;}else if(sim.buildings.length){$('hint').hidden=true;}else{$('hint').innerHTML='<span>BEGIN ANYWHERE</span> Place a shelter in the clearing. Your settlers will build it.';$('hint').hidden=false;}
 updateInspector();renderer.drawMini(sim);}
load();updateUI();
function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;if(!document.hidden&&!document.querySelector('dialog[open]')){let remaining=dt*speed;while(remaining>0){const step=Math.min(.05,remaining);sim.update(step);remaining-=step;}const pan=dt*380/renderer.camera.zoom;if(keys.has('a')||keys.has('arrowleft'))renderer.camera.x-=pan;if(keys.has('d')||keys.has('arrowright'))renderer.camera.x+=pan;if(keys.has('w')||keys.has('arrowup'))renderer.camera.y-=pan;if(keys.has('s')||keys.has('arrowdown'))renderer.camera.y+=pan;}renderer.draw(sim,now/1000);uiClock+=dt;saveClock+=dt;if(uiClock>.35){updateUI();uiClock=0;}if(saveClock>30){save();saveClock=0;}requestAnimationFrame(frame);}requestAnimationFrame(frame);

import {registerGameTools} from './agent-tools.mjs';
registerGameTools({read:()=>({day:Math.floor(sim.time/120)+1,resources:{...sim.resources},speed,people:sim.people.map(p=>({name:p.name,x:p.x,y:p.y,action:p.action,trade:p.trait,morale:Math.round(p.morale)})),buildings:sim.buildings.map(b=>({id:b.id,type:b.type,x:b.x,y:b.y,complete:b.complete,condition:Math.round(b.condition)})),marked:sim.nodes.filter(n=>n.marked).map(n=>({id:n.id,type:n.type,x:n.x,y:n.y}))}),place:(type,x,y)=>{const result=sim.place(type,x,y);updateUI();if(result.ok)toast(DEFINITIONS[type].name+' planned.');return result;},speed:value=>{setSpeed(value);updateUI();return {speed};}});
